        uint balBefore = address(c).balance;
        bool ok1 = c.setOwner(x); if (__ESBMC_reverted()) return;
        uint balMid = address(c).balance;
        bool ok2 = c.setOwner(y); if (__ESBMC_reverted()) return;
        address finalOwner = c.owner(); if (__ESBMC_reverted()) return;
